THOUGHT: The original METHOD_NO_INIT error on the constructor is gone, but now NullAway flags `data` dereferences because it’s annotated @Nullable and later set to null. The intended invariant is: after `prepare()` succeeds, `data` is non-null until `consumeCustomData` finishes. I can encode this by (1) keeping `data` nullable, (2) in `prepare()`, throwing if `data` is null before using it, and (3) in `consumeCustomData`, copying `data` into a local non-null variable after checking `isPrepared`, then using that local and nulling the field afterward. This preserves behavior and gives NullAway a clear non-null value for all dereferences. I’ll update `prepare()` and `consumeCustomData()` accordingly, then rebuild and re-check the ETC1TextureData errors and overall NullAway count.

```bash
cd /home/vscode/nullness-benchmarks/libgdx && sed -i '62,72c\  @Override
  public void prepare() {
    if (isPrepared) throw new GdxRuntimeException("Already prepared");
    if (file == null && data == null)
      throw new GdxRuntimeException("Can only load once from ETC1Data");
    if (file != null) {
      data = new ETC1Data(file);
    }
    if (data == null) {
      throw new GdxRuntimeException("ETC1Data is null in prepare()");
    }
    width = data.width;
    height = data.height;
    isPrepared = true;
  }' gdx/src/com/badlogic/gdx/graphics/glutils/ETC1TextureData.java && sed -i '74,110c\  @Override
  public void consumeCustomData(int target) {
    if (!isPrepared)
      throw new GdxRuntimeException("Call prepare() before calling consumeCompressedData()");

    ETC1Data localData = data;
    if (localData == null) {
      throw new GdxRuntimeException("ETC1Data is null in consumeCustomData()");
    }

    if (!Gdx.graphics.supportsExtension("GL_OES_compressed_ETC1_RGB8_texture")) {
      Pixmap pixmap = ETC1.decodeImage(localData, Format.RGB565);
      Gdx.gl.glTexImage2D(
          target,
          0,
          pixmap.getGLInternalFormat(),
          pixmap.getWidth(),
          pixmap.getHeight(),
          0,
          pixmap.getGLFormat(),
          pixmap.getGLType(),
          pixmap.getPixels());
      if (useMipMaps)
        MipMapGenerator.generateMipMap(target, pixmap, pixmap.getWidth(), pixmap.getHeight());
      pixmap.dispose();
      useMipMaps = false;
    } else {
      Gdx.gl.glCompressedTexImage2D(
          target,
          0,
          ETC1.ETC1_RGB8_OES,
          width,
          height,
          0,
          localData.compressedData.capacity() - localData.dataOffset,
          localData.compressedData);
      if (useMipMaps()) Gdx.gl20.glGenerateMipmap(GL20.GL_TEXTURE_2D);
    }
    localData.dispose();
    data = null;
    isPrepared = false;
  }' gdx/src/com/badlogic/gdx/graphics/glutils/ETC1TextureData.java && ./gradlew gdx:compileJava -x test -q > new_build_output.log 2>&1 && { echo "=== ETC1TextureData in new log ==="; grep -n "ETC1TextureData" new_build_output.log || true; echo "=== NullAway error counts ==="; echo "initial:"; grep -n "NullAway" initial_build_output.log | tail -n 1; echo "new:"; grep -n "NullAway" new_build_output.log | tail -n 1; }
```

